package enrich

import (
	"context"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/module"
	"github.com/mellifera/mellifera/pkg/sdk"
	metadatav1 "github.com/mellifera/mellifera/proto/mellifera/metadata/v1"
	scannerv1 "github.com/mellifera/mellifera/proto/mellifera/scanner/v1"
	"google.golang.org/protobuf/types/known/structpb"
)

// planSource hands runSource the request plan under test: a primary spec plus
// an ordered extra plan (media-data convention D4). It captures the
// ConvertRequest the core builds from the plan's outcomes, and converts the
// plan into a namespace field (extras_fetched) so a test can see what the
// run gained from what actually arrived.
type planSource struct {
	sdk.UnsupportedSearch // the interactive search pair: unsupported (identify-match-override)
	primary               *metadatav1.RequestSpec
	extras                []*metadatav1.RequestSpec
	onConvert             func(*metadatav1.ConvertRequest)
	converted             bool
}

var _ sdk.MetadataSource = (*planSource)(nil)

func (s *planSource) Match(context.Context, *metadatav1.MatchRequest) (*metadatav1.MatchResult, error) {
	return &metadatav1.MatchResult{Applies: true}, nil
}

func (s *planSource) BuildRequest(context.Context, *metadatav1.BuildRequestRequest) (*metadatav1.BuildRequestResponse, error) {
	return &metadatav1.BuildRequestResponse{Spec: s.primary, ExtraSpecs: s.extras}, nil
}

func (s *planSource) Convert(_ context.Context, req *metadatav1.ConvertRequest) (*metadatav1.ConvertResult, error) {
	s.converted = true
	if s.onConvert != nil {
		s.onConvert(req)
	}
	fetched := 0
	for _, fr := range req.GetExtraResponses() {
		if fr.GetFetched() {
			fetched++
		}
	}
	md, _ := structpb.NewStruct(map[string]any{"title": "plan", "extras_fetched": int64(fetched)})
	return &metadatav1.ConvertResult{Metadata: md}, nil
}

func (s *planSource) Merge(_ context.Context, req *metadatav1.MergeRequest) (*metadatav1.MergeResult, error) {
	return &metadatav1.MergeResult{Document: wrapNamespace("plan", req.GetIncoming(), false)}, nil
}

// runPlan drives the sync enrichDoc chain over the plan source (plugin id
// "plan", enabled).
func runPlan(t *testing.T, src *planSource) map[string]any {
	t.Helper()
	resolve := func(string, string) (sdk.MetadataSource, error) { return src, nil }
	mod := module.Module{ID: "serial", MediaType: "serial", MetadataSources: []module.MetadataSourceBinding{binding("plan", 1, true)}}
	doc, _, _, err := enrichDoc(context.Background(), resolve, mod, map[string]any{}, &scannerv1.IdentifyResult{}, nil)
	if err != nil {
		t.Fatalf("enrichDoc: %v", err)
	}
	return doc
}

// TestRequestPlan is media-data convention box 2.1: the ordered request plan —
// extras fetched after the primary in order and aligned into ConvertRequest,
// a failed extra soft-failing its own entry while the run continues (the
// primary failure path unchanged), and pacing spanning the plan on the
// injectable clock.
func TestRequestPlan(t *testing.T) {
	t.Run("ordered delivery: extras fetched in order, aligned into ConvertRequest", func(t *testing.T) {
		rec := &fetchRecorder{}
		srv := httptest.NewServer(rec)
		defer srv.Close()
		convSeen := make(chan *metadatav1.ConvertRequest, 1)
		src := &planSource{
			primary: &metadatav1.RequestSpec{Method: "GET", UrlTemplate: srv.URL + "?which=primary"},
			extras: []*metadatav1.RequestSpec{
				{Method: "GET", UrlTemplate: srv.URL + "?which=extra1"},
				{Method: "GET", UrlTemplate: srv.URL + "?which=extra2"},
			},
			onConvert: func(cr *metadatav1.ConvertRequest) { convSeen <- cr },
		}
		doc := runPlan(t, src)

		// Upstream order: primary first, then the extras in plan order.
		got := []string{rec.query(0), rec.query(1), rec.query(2)}
		want := []string{"which=primary", "which=extra1", "which=extra2"}
		for i := range want {
			if got[i] != want[i] {
				t.Fatalf("upstream hit %d query = %q, want %q (primary first, extras in plan order)", i, got[i], want[i])
			}
		}
		cr := <-convSeen
		// The primary stays in the singular fields; each extra lands at its
		// own position with its own body, status, and headers.
		if string(cr.GetRawResponse()) != `{"id":1,"n":1}` {
			t.Fatalf("raw_response = %q, want the primary's body", cr.GetRawResponse())
		}
		extras := cr.GetExtraResponses()
		if len(extras) != 2 {
			t.Fatalf("len(extra_responses) = %d, want 2", len(extras))
		}
		for i, wantBody := range []string{`{"id":1,"n":2}`, `{"id":1,"n":3}`} {
			fr := extras[i]
			if !fr.GetFetched() {
				t.Fatalf("extra_responses[%d].fetched = false, want true", i)
			}
			if string(fr.GetBody()) != wantBody {
				t.Fatalf("extra_responses[%d].body = %q, want %q", i, fr.GetBody(), wantBody)
			}
			if fr.GetHttpStatus() != http.StatusOK {
				t.Fatalf("extra_responses[%d].http_status = %d, want 200", i, fr.GetHttpStatus())
			}
			if fr.GetHeaders()["X-Trace"] != "t-1" {
				t.Fatalf("extra_responses[%d].headers[X-Trace] = %v, want t-1", i, fr.GetHeaders())
			}
			if fr.GetError() != "" {
				t.Fatalf("extra_responses[%d].error = %q, want empty", i, fr.GetError())
			}
		}
		// The run gained what Convert built from the full plan.
		// structpb numbers decode as float64 through AsMap.
		if f, _ := nested(doc, "sources", "plan", "extras_fetched").(float64); f != 2 {
			t.Fatalf("sources.plan.extras_fetched = %v, want 2", nested(doc, "sources", "plan", "extras_fetched"))
		}
	})

	t.Run("soft-failed extra: not-fetched entry with error, the run continues", func(t *testing.T) {
		rec := &fetchRecorder{}
		srv := httptest.NewServer(rec)
		defer srv.Close()
		convSeen := make(chan *metadatav1.ConvertRequest, 1)
		src := &planSource{
			primary: &metadatav1.RequestSpec{Method: "GET", UrlTemplate: srv.URL + "?which=primary"},
			extras: []*metadatav1.RequestSpec{
				{Method: "GET", UrlTemplate: srv.URL + "?which={missing}"}, // this extra's validation fails
			},
			onConvert: func(cr *metadatav1.ConvertRequest) { convSeen <- cr },
		}
		doc := runPlan(t, src)

		// The failed extra never touched the network; the primary did.
		if n := rec.count(); n != 1 {
			t.Fatalf("upstream saw %d requests, want 1 (the primary only)", n)
		}
		// The failed entry is aligned at its position: fetched=false with the
		// error, body/status unset.
		extras := (<-convSeen).GetExtraResponses()
		if len(extras) != 1 {
			t.Fatalf("len(extra_responses) = %d, want 1 (alignment preserved)", len(extras))
		}
		fr := extras[0]
		if fr.GetFetched() {
			t.Fatal("extra_responses[0].fetched = true, want false")
		}
		if !strings.Contains(fr.GetError(), "{missing}") {
			t.Fatalf("extra_responses[0].error = %q, want the placeholder failure", fr.GetError())
		}
		if len(fr.GetBody()) != 0 || fr.GetHttpStatus() != 0 || len(fr.GetHeaders()) != 0 {
			t.Fatalf("failed entry carries body/status/headers = %q/%d/%v, want unset", fr.GetBody(), fr.GetHttpStatus(), fr.GetHeaders())
		}
		// The run continues: Convert ran and the namespace still landed.
		if f, _ := nested(doc, "sources", "plan", "extras_fetched").(float64); f != 0 {
			t.Fatalf("sources.plan.extras_fetched = %v, want 0 (the failed extra soft-failed its entry only)", nested(doc, "sources", "plan", "extras_fetched"))
		}
		if st := stages(doc); len(st) == 0 || st[0]["status"] != "ok" {
			t.Fatalf("stage = %v, want status ok (a failed extra never fails the run)", st)
		}
	})

	t.Run("primary failure unchanged: the run fails at fetch, Convert never runs", func(t *testing.T) {
		rec := &fetchRecorder{}
		srv := httptest.NewServer(rec)
		defer srv.Close()
		src := &planSource{
			primary: &metadatav1.RequestSpec{Method: "GET", UrlTemplate: srv.URL + "?which={missing}"},
			extras:  []*metadatav1.RequestSpec{{Method: "GET", UrlTemplate: srv.URL + "?which=extra1"}},
		}
		doc := runPlan(t, src)

		if n := rec.count(); n != 0 {
			t.Fatalf("upstream saw %d requests, want 0 (primary validation precedes any network)", n)
		}
		if src.converted {
			t.Fatal("Convert ran after a failed primary; the primary failure path must be unchanged")
		}
		if got := nested(doc, "sources", "plan"); got != nil {
			t.Fatalf("sources.plan = %v, want absent", got)
		}
		st := stages(doc)
		if len(st) == 0 || st[0]["status"] != "failed" {
			t.Fatalf("stage = %v, want status failed", st)
		}
		if err, _ := st[0]["error"].(string); !strings.HasPrefix(err, "fetch:") {
			t.Fatalf("stage error = %q, want a fetch-stage failure", err)
		}
	})

	t.Run("interval spacing: pacing spans the plan on the injectable clock", func(t *testing.T) {
		var mu sync.Mutex
		at := testTime
		var hits []time.Time
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
			mu.Lock()
			at = at.Add(10 * time.Millisecond) // the fake clock steps once per upstream hit
			hits = append(hits, time.Now())
			mu.Unlock()
			w.Header().Set("Content-Type", "application/json")
			_, _ = w.Write([]byte(`{"ok":true}`))
		}))
		defer srv.Close()
		gate := newFetchGate(func() time.Time {
			mu.Lock()
			defer mu.Unlock()
			return at
		})
		spec := func(which string) *metadatav1.RequestSpec {
			return &metadatav1.RequestSpec{Method: "GET", UrlTemplate: srv.URL + "?which=" + which, MinIntervalMs: 100}
		}
		// runSource is the fetch point the gate flows through (the sync
		// enrichDoc path is unpaced), so the plan runs through it directly.
		mod := module.Module{ID: "serial", MediaType: "serial"}
		res := runSource(context.Background(), func(string, string) (sdk.MetadataSource, error) {
			return &planSource{primary: spec("primary"), extras: []*metadatav1.RequestSpec{spec("extra1"), spec("extra2")}}, nil
		}, binding("plan", 1, true), mod, &scannerv1.IdentifyResult{}, map[string]any{}, gate, nil)
		if res.kind != outcomeSucceeded {
			t.Fatalf("runSource kind = %v (err %q), want succeeded", res.kind, res.errMsg)
		}

		mu.Lock()
		defer mu.Unlock()
		if len(hits) != 3 {
			t.Fatalf("upstream saw %d hits, want 3 (primary + two extras)", len(hits))
		}
		// The waits come from the injectable clock: after each hit the fake
		// clock has advanced only 10ms, so each next send of the plan reserves
		// a 90ms/80ms slot it must actually wait out. An unpaced plan-mate
		// would arrive within milliseconds of its predecessor.
		if gap := hits[1].Sub(hits[0]); gap < 80*time.Millisecond {
			t.Fatalf("primary -> extra1 gap = %v, want >= 80ms (the 100ms interval spans the plan)", gap)
		}
		if gap := hits[2].Sub(hits[1]); gap < 70*time.Millisecond {
			t.Fatalf("extra1 -> extra2 gap = %v, want >= 70ms", gap)
		}
	})
}
